// Sort and filter for the store listing grids.
//
// Injected by _tools/add-store-filters.js, alongside assets/js/store-facets.js
// (generated by _tools/build-store-facets.js), which supplies window.FCE_FACETS.
//
// WHY THIS EXISTS
// ---------------
// The listing grids run to 53 tiles with no way to narrow them, and until now
// no listing page carried any interactive JS at all beyond the Weebly theme. A
// host looking for a printable music bingo game under $15 had to read the lot.
//
// THINGS THAT ARE DELIBERATE
// --------------------------
// * NO TILE MARKUP IS TOUCHED, here or by the tool. Facets are looked up by the
//   data-id the tile already carries. add-store-tile.js and order-store-tiles.js
//   both match a tile with the ">" immediately after data-id, so an extra
//   attribute would make them find zero tiles -- while check-tile-structure.js,
//   which does not require that ">", carried on reporting every tile well
//   formed. An all-clear over a broken tool is the failure this repo keeps
//   hitting, so the safe move is to add nothing to a tile at all.
//
// * "On sale" is read off the tile's own sale classes rather than from the
//   facet file, so it can never disagree with the price the page shows or the
//   checkout charges.
//
// * Sorting sets CSS `order` on the flex grid instead of moving nodes. The
//   curated per-page sequence order-store-tiles.js produces (packs first on the
//   storefront, singles first on c11) stays the DOM order and stays the default,
//   and no tile is ever re-appended, so the delegated select_item tracking in
//   track.js keeps working.
//
// * A filter chip only appears when at least two tiles on THIS page carry a
//   value for it. A half-filled facet hides itself rather than offering a
//   filter that returns nothing.
//
// * A null facet never matches. A product is only included on a value somebody
//   set deliberately.
//
// * Nothing is removed from the HTML, so every tile stays crawlable. With JS
//   off, the controls never render and all tiles show.
(function () {
  "use strict";

  var FACETS = window.FCE_FACETS || {};
  var BEST = window.FCE_BESTSELLERS || [];

  // key, chip label, and the test a tile must pass. Order here is the order the
  // chips render in.
  var FILTERS = [
    ["sale", "On sale", function (t) { return t.onSale; }],
    ["music", "Music bingo", function (t) { return t.f.type === "music-bingo"; }],
    ["trivia", "Trivia show", function (t) { return t.f.type === "trivia-show"; }],
    ["printable", "Printable", function (t) { return t.f.printable === true; }],
    ["challenging", "More challenging", function (t) { return t.f.challenging === true; }],
    ["family", "Family friendly", function (t) { return t.f.family === true; }],
    ["playlist", "Playlist included", function (t) { return t.f.playlist === true; }],
    ["songlist", "Free song list", function (t) { return t.f.songlist === true; }],
    ["pack", "Multi-game pack", function (t) { return t.f.games > 1; }],
  ];

  var SORTS = [
    ["featured", "Featured"],
    ["price-asc", "Price: low to high"],
    ["price-desc", "Price: high to low"],
    // One game runs a room for about an hour, so this is also price per hour.
    ["per-game", "Best value per game"],
    ["best", "Best selling"],
  ];

  function money(el) {
    if (!el) return null;
    var t = (el.textContent || "").replace(/[^0-9.]/g, "");
    // The two Amazon titles render the literal string "On Amazon" and have no
    // number to sort on.
    return t ? parseFloat(t) : null;
  }

  function collect(grid) {
    var nodes = grid.querySelectorAll(
      ".wsite-com-category-product, .wsite-com-category-product-featured"
    );
    var out = [];
    for (var i = 0; i < nodes.length; i++) {
      var el = nodes[i];
      var id = el.getAttribute("data-id");
      if (!id) continue;
      var onSale = !!el.querySelector(".category__image-sale-banner-wrapper.sale-active") ||
        !!el.querySelector(".wsite-com-product-price.single-sale-price");
      var price = money(el.querySelector(onSale ? ".wsite-com-sale-price" : ".wsite-com-price"));
      var f = FACETS["p" + id] || {};
      out.push({
        el: el, pid: "p" + id, f: f, onSale: onSale, price: price,
        perGame: (price != null && f.games > 0) ? price / f.games : null,
        best: BEST.indexOf("p" + id),
        seq: i,
      });
    }
    return out;
  }

  function build(host, tiles) {
    var active = {}, sort = "featured";

    var row = document.createElement("div");
    row.className = "fce-filters-row";

    var chips = [];
    for (var i = 0; i < FILTERS.length; i++) {
      var key = FILTERS[i][0], label = FILTERS[i][1], test = FILTERS[i][2];
      var n = 0;
      for (var j = 0; j < tiles.length; j++) if (test(tiles[j])) n++;
      // Two is the floor: one match is not a filter, and a facet that matches
      // every tile on the page narrows nothing.
      if (n < 2 || n === tiles.length) continue;
      var b = document.createElement("button");
      b.type = "button";
      b.className = "fce-chip";
      b.setAttribute("data-key", key);
      b.setAttribute("data-fce-event", "store_filter");
      b.setAttribute("data-fce-label", key);
      b.textContent = label + " (" + n + ")";
      row.appendChild(b);
      chips.push(b);
    }

    var tools = document.createElement("div");
    tools.className = "fce-filters-tools";

    var sel = document.createElement("select");
    sel.className = "fce-filters-sort";
    sel.setAttribute("aria-label", "Sort products");
    for (var s = 0; s < SORTS.length; s++) {
      // No invented ranking: without an owner-supplied order the option is not
      // offered at all.
      if (SORTS[s][0] === "best" && !BEST.length) continue;
      var o = document.createElement("option");
      o.value = SORTS[s][0];
      o.textContent = SORTS[s][1];
      sel.appendChild(o);
    }

    var count = document.createElement("span");
    count.className = "fce-filters-count";
    var clear = document.createElement("button");
    clear.type = "button";
    clear.className = "fce-filters-clear";
    clear.textContent = "Clear";
    clear.hidden = true;

    tools.appendChild(sel);
    tools.appendChild(count);
    tools.appendChild(clear);

    var empty = document.createElement("p");
    empty.className = "fce-filters-empty";
    empty.textContent = "Nothing matches all of those. Try clearing one.";
    empty.hidden = true;

    if (chips.length) host.appendChild(row);
    host.appendChild(tools);
    host.appendChild(empty);
    host.className += " fce-filters--ready";

    function shown(t) {
      for (var k in active) {
        if (!active[k]) continue;
        var f = null;
        for (var i2 = 0; i2 < FILTERS.length; i2++) if (FILTERS[i2][0] === k) f = FILTERS[i2][2];
        if (f && !f(t)) return false;
      }
      return true;
    }

    function apply() {
      var n = 0, i2;
      for (i2 = 0; i2 < tiles.length; i2++) {
        var t = tiles[i2];
        var on = shown(t);
        t.el.style.display = on ? "" : "none";
        if (on) n++;
      }

      var visible = [];
      for (i2 = 0; i2 < tiles.length; i2++) if (tiles[i2].el.style.display !== "none") visible.push(tiles[i2]);

      // A tile with nothing to sort on keeps its curated position at the back
      // rather than being guessed at or dropped.
      function rank(t) {
        if (sort === "price-asc") return t.price == null ? Infinity : t.price;
        if (sort === "price-desc") return t.price == null ? Infinity : -t.price;
        if (sort === "per-game") return t.perGame == null ? Infinity : t.perGame;
        if (sort === "best") return t.best < 0 ? Infinity : t.best;
        return t.seq;
      }
      visible.sort(function (a, b) {
        var ra = rank(a), rb = rank(b);
        if (ra === rb) return a.seq - b.seq;
        return ra - rb;
      });
      for (i2 = 0; i2 < visible.length; i2++) visible[i2].el.style.order = i2 + 1;

      count.textContent = n === tiles.length
        ? "Showing all " + tiles.length
        : "Showing " + n + " of " + tiles.length;
      empty.hidden = n !== 0;
      var any = false;
      for (var k in active) if (active[k]) any = true;
      clear.hidden = !any && sort === "featured";
      writeHash();
    }

    function writeHash() {
      var keys = [];
      for (var k in active) if (active[k]) keys.push(k);
      var parts = [];
      if (keys.length) parts.push("f=" + keys.join(","));
      if (sort !== "featured") parts.push("s=" + sort);
      // A hash, never a query string: this must not mint a second crawlable URL
      // for a page that already has two live forms (see "URL shape" in CLAUDE.md).
      var next = parts.length ? "#" + parts.join("&") : " ";
      if (history && history.replaceState) history.replaceState(null, "", next === " " ? location.pathname : next);
    }

    function readHash() {
      var h = (location.hash || "").replace(/^#/, "");
      if (!h) return;
      var parts = h.split("&");
      for (var i2 = 0; i2 < parts.length; i2++) {
        var kv = parts[i2].split("=");
        if (kv[0] === "f" && kv[1]) {
          var ks = kv[1].split(",");
          for (var j2 = 0; j2 < ks.length; j2++) active[ks[j2]] = true;
        }
        if (kv[0] === "s" && kv[1]) sort = kv[1];
      }
      for (var c = 0; c < chips.length; c++) {
        if (active[chips[c].getAttribute("data-key")]) chips[c].className = "fce-chip fce-chip--on";
      }
      sel.value = sort;
      if (sel.value !== sort) sort = "featured";
    }

    row.addEventListener("click", function (ev) {
      var chip = ev.target.closest && ev.target.closest(".fce-chip");
      if (!chip) return;
      var key = chip.getAttribute("data-key");
      active[key] = !active[key];
      chip.className = active[key] ? "fce-chip fce-chip--on" : "fce-chip";
      apply();
    });
    sel.addEventListener("change", function () { sort = sel.value; apply(); });
    clear.addEventListener("click", function () {
      active = {};
      sort = "featured";
      sel.value = "featured";
      for (var c = 0; c < chips.length; c++) chips[c].className = "fce-chip";
      apply();
    });

    readHash();
    apply();
  }

  function init() {
    var host = document.querySelector("[data-fce-filters]");
    var grid = document.getElementById("wsite-com-category-product-group");
    if (!host || !grid) return;
    var tiles = collect(grid);
    // Not worth a control bar over a handful of tiles.
    if (tiles.length < 6) return;
    build(host, tiles);
  }

  // Never let this break a listing page: a grid that does not filter is a grid,
  // a grid that throws mid-render is a blank page.
  function safe() { try { init(); } catch (e) { /* no-op */ } }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", safe);
  else safe();
})();
